param([ValidateSet('Scan','WindowsUpdate','Backup','Official','BIOS')][string]$Mode,[string]$BackupDir)
if($Mode -eq 'Scan'){Get-CimInstance Win32_PnPSignedDriver|Where-Object {$_.DeviceName -and $_.DriverVersion}|Sort-Object DeviceName|Select-Object DeviceName,Manufacturer,DriverVersion,@{N='Fecha';E={$_.DriverDate}}|Format-Table -AutoSize;exit}
if($Mode -eq 'Backup'){$d=Join-Path $BackupDir ('Drivers_'+(Get-Date -Format yyyyMMdd_HHmmss));New-Item $d -ItemType Directory -Force|Out-Null;pnputil /export-driver * $d;Write-Host ('Backup: '+$d);exit}
if($Mode -eq 'WindowsUpdate'){Write-Host 'Abriendo Windows Update > Actualizaciones opcionales.';Start-Process 'ms-settings:windowsupdate-optionalupdates';exit}
$cs=Get-CimInstance Win32_ComputerSystem;$gpu=Get-CimInstance Win32_VideoController|Select-Object -First 1;$bios=Get-CimInstance Win32_BIOS
if($Mode -eq 'BIOS'){Write-Host ('Fabricante: '+$cs.Manufacturer);Write-Host ('Modelo: '+$cs.Model);Write-Host ('BIOS: '+$bios.SMBIOSBIOSVersion+' | '+$bios.ReleaseDate);Write-Host 'WinTool no descarga ni instala BIOS automaticamente.';exit}
Write-Host ('Equipo: '+$cs.Manufacturer+' '+$cs.Model);Write-Host ('GPU: '+$gpu.Name);$urls=@();if($gpu.Name -match 'AMD|Radeon'){$urls+='https://www.amd.com/en/support/download/drivers.html'};if($gpu.Name -match 'NVIDIA'){$urls+='https://www.nvidia.com/Download/index.aspx'};if($gpu.Name -match 'Intel'){$urls+='https://www.intel.com/content/www/us/en/support/detect.html'};if($cs.Manufacturer -match 'Micro-Star|MSI'){$urls+='https://www.msi.com/support'};if(!$urls){Write-Host 'No se detecto una pagina especifica con seguridad. Usa la web oficial del fabricante.'}else{$urls|ForEach-Object{Write-Host ('OFICIAL: '+$_);$a=Read-Host 'Abrir esta pagina? [S/N]';if($a -match '^[Ss]'){Start-Process $_}}}
